import { ImageViewer, type ImageViewerChangeDetail } from '@absoluteui/components/image-viewer';

const host = document.createElement('div');
document.body.append(host);
const viewer = ImageViewer.create(host, {
  label: 'Expense receipts',
  images: [
    { src: '/images/receipts-taxi.png', alt: 'Taxi receipt, 42 euros, 3 March', caption: 'Taxi to the airport' },
    { src: '/images/receipts-hotel.png', alt: 'Hotel invoice, two nights', downloadName: 'hotel-invoice.jpg' },
  ],
});
host.addEventListener('aui-change', (event) => {
  host.dataset.shown = String((event as CustomEvent<ImageViewerChangeDetail>).detail.index);
});
viewer.zoomIn();

import { ImageViewer, type ImageViewerCropDetail } from '@absoluteui/components/image-viewer';

const trigger = document.createElement('button');
trigger.textContent = 'Edit photo';
const host = document.createElement('div');
document.body.append(trigger, host);
const viewer = ImageViewer.create(host, {
  label: 'Profile photo',
  mode: 'lightbox',
  croppable: true,
  images: [{ src: '/images/people-ada.png', alt: 'Ada Lovelace smiling' }],
  crossOrigin: 'anonymous',
  cropType: 'image/jpeg',
  cropQuality: 0.9,
});
trigger.addEventListener('click', () => {
  viewer.open(0);
});
host.addEventListener('aui-crop', (event) => {
  const { blob, rect } = (event as CustomEvent<ImageViewerCropDetail>).detail;
  host.dataset.size = `${String(rect.width)}x${String(rect.height)} ${String(blob.size)} bytes`;
  viewer.close();
});
